/* Modo temporal: a preparação e a execução são ações separadas. */
let videoBusy=false;
(()=>{
const root=$('videoView');
const style=document.createElement('style');style.textContent=`
#vBars{width:100%;height:180px;background:#f5f8fb;border-radius:6px;touch-action:pan-y;user-select:none}#vBars rect:focus{stroke:#111;stroke-width:2}#vBarReading{min-height:24px;margin-top:10px}#vBarRange{margin:6px 0}
.videoFields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.videoFields input[type=number]{width:100%;padding:9px;border:1px solid #9babb8;border-radius:6px}.videoActions{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.videoActions button{width:auto}.videoFrames{display:grid;grid-template-columns:repeat(auto-fill,minmax(145px,1fr));gap:12px;margin:18px 0}.videoFrame{border:1px solid var(--line);border-radius:8px;background:#f6f9fb;padding:10px;text-align:left}.videoFrame[aria-pressed=true]{outline:3px solid var(--blue)}.videoFrame img{width:100%;height:90px;object-fit:contain}.videoFrame span{display:block;font-size:12px}.videoPreview{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:20px 0}.videoPreview img,.videoPreview video,.videoPreview canvas{width:100%;height:280px;object-fit:contain;background:#e8eef2;border-radius:8px}.videoFrame:nth-child(4n+1),.videoFrame:nth-child(4n+2){background:#eaf4f1}#vChart{width:100%;height:220px;background:#f5f8fb;border-radius:8px}#vSlider{width:100%}@media(max-width:700px){.videoFields,.videoPreview{grid-template-columns:1fr}.videoPreview img,.videoPreview video,.videoPreview canvas{height:220px}}`;
document.head.append(style);
root.innerHTML=`<div class="intro"><div><h1>Veja a sequência que entra no encoder</h1><p>Escolha um vídeo ou GIF, prepare uma amostra e examine os quadros. Você inicia a execução depois de conferir a entrada.</p></div><span class="badge">Somente visão · pesos congelados</span></div>
<section class="panel batchsettings"><h2>1. Escolha o vídeo ou GIF</h2><p class="small">Até 50 MB. MP4, WebM, MOV, outros formatos reconhecidos pelo leitor e GIF. Analisamos apenas os quadros; o áudio não entra.</p>
<input id="vFile" type="file" accept="video/*,image/gif,.mkv,.avi" aria-label="Escolher vídeo ou GIF"><div class="copy-warning" role="note"><span class="copy-warning-icon" aria-hidden="true">⚠</span><span><strong>Cópia local:</strong> fazer upload vai gravar nesta máquina uma cópia deste vídeo ou GIF.</span></div><p id="vStatus" role="status" class="small" style="margin-top:12px">Escolha um arquivo para começar.</p>
<div id="vOriginalBox" class="hidden"><div class="videoPreview"><div><h3>Arquivo original</h3><video id="vOriginalVideo" controls preload="metadata" class="hidden"></video><img id="vOriginalGif" alt="GIF original animado" class="hidden"><p class="small">A reprodução original não indica quais quadros serão analisados.</p></div><div><h3>Condições da amostra</h3><p id="vMeta"></p><p>O intervalo é amostrado uniformemente no tempo. Cada instante usa o quadro ativo naquele momento. Trechos quase parados podem repetir quadros.</p><p class="small">Selecione até 60 segundos, dentro dos primeiros 10 minutos. Comece com 4 ou 8 quadros para experimentar na CPU.</p></div></div></div>
<div id="vDurationBox" class="callout hidden" style="margin:16px 0 22px"><p style="font-size:22px"><strong>Duração total: <span id="vDuration"></span></strong></p><p id="vDurationNote" class="small"></p></div><div class="videoFields"><div><label for="vStart">Início (segundos)</label><input id="vStart" type="number" min="0" step="any" value="0"></div><div><label for="vEnd">Fim (segundos, não incluído)</label><input id="vEnd" type="number" min="0" step="any" value="4" aria-describedby="vEndHelp vTimeError"></div><div><label for="vCount">Quadros selecionados</label><select id="vCount"><option value="2">2 quadros · 1 par</option><option value="4">4 quadros · 2 pares</option><option value="8" selected>8 quadros · 4 pares</option><option value="16">16 quadros · 8 pares</option></select></div><div><label for="vLimit">Orçamento de pixels por quadro</label><select id="vLimit"><option value="128">16.384 pixels</option><option value="192" selected>36.864 pixels</option><option value="256">65.536 pixels</option></select></div><div><label for="vBackground">Fundo para transparência</label><input id="vBackground" type="color" value="#ffffff"></div></div>
<p id="vEndHelp" class="small" style="margin-top:12px"></p><button id="vUseEnd" class="secondary" disabled>Usar fim do arquivo</button><p id="vTimeError" role="status" class="error hidden" style="margin-top:12px"></p><p class="small" style="margin-top:12px">A proporção é preservada aproximadamente; largura e altura se ajustam a múltiplos de 32.</p><button id="vPrepare" class="primary" disabled>Preparar sequência</button></section>
<section id="vPreparedPanel" class="panel batchsettings hidden"><h2>2. Confira os quadros preparados</h2><p id="vSummary"></p><p>Cada par temporal reúne dois quadros selecionados. Os pares seguem a ordem da amostra; não são duas cópias da mesma imagem, exceto quando a amostragem repete um quadro.</p><p id="vRepeated" class="small"></p>
<div class="videoPreview"><div><h3>Quadro selecionado · fundo aplicado</h3><img id="vSelectedOriginal" alt="Quadro amostrado antes do redimensionamento"></div><div><h3>Entrada real preparada</h3><canvas id="vCanvas" aria-label="Quadro reconstruído dos tensores enviados ao encoder"></canvas></div></div>
<label for="vSlider">Percorra a sequência</label><input id="vSlider" type="range" min="0" max="7" value="0"><p id="vFrameCaption" class="small"></p><div class="videoActions"><button id="vPlay" class="secondary">Reproduzir amostra · 2 quadros/s</button><label><input id="vGrid" type="checkbox"> Mostrar patches de 16 × 16</label></div><div id="vFrames" class="videoFrames"></div>
<details><summary>Ver a preparação e os tempos exatos</summary><pre id="vRecord"></pre></details>
<label for="vNotes">Minhas observações</label><textarea id="vNotes" placeholder="O que muda entre os quadros? O que você espera encontrar?"></textarea>
<div id="videoRecipe"></div><button id="vRun" class="primary">3. Executar esta sequência no encoder</button><progress id="vProgress" max="27" value="0" style="margin-top:16px"></progress><p id="vRunStatus" role="status" class="small">Entrada preparada. O encoder ainda não foi executado.</p></section>
<section id="vResults" class="panel batchsettings hidden"><h2>Representações da sequência</h2><p id="vShapes"></p><p>Guardamos todos os tokens antes e depois do merger. O gráfico usa a agregação e a normalização escolhidas. Essas operações são escolhas da bancada.</p><p id="vAppliedRecipe" class="analysis-readout"></p><div class="analysis-stage"><label for="vStage">Representação exibida</label><select id="vStage"><option value="after">Depois do merger</option><option value="before">Antes do merger</option></select></div><label for="vPair">O que visualizar</label><select id="vPair"></select><section style="margin-top:22px"><h3>Coordenadas em barras</h3><p class="small">48 coordenadas por vez. Role até a última coordenada mantendo a largura das barras. Azul: valor positivo; laranja: negativo. Clique ou use Tab para consultar o valor exato.</p><svg id="vBars" viewBox="0 0 720 180" role="img" aria-label="Janela de 48 coordenadas do vetor de vídeo"></svg><div id="vBarScroll" class="barScroll" role="region" tabindex="0" aria-label="Rolar pelas coordenadas do vídeo em barras"><div id="vBarScrollSpace"></div></div><p id="vBarRange" class="small" aria-live="polite"></p><p id="vBarReading" class="small" aria-live="polite"></p><p id="vBarScale" class="small"></p></section><h3 style="margin-top:24px">O vetor inteiro em linha</h3><svg id="vChart" viewBox="0 0 1000 220" role="img" aria-label="4096 coordenadas do vetor médio normalizado da sequência ou do par temporal"></svg><p id="vReading" class="small">Passe o ponteiro pelo gráfico para consultar uma coordenada.</p><p class="small">Horizontal: coordenadas do estágio selecionado. Vertical: valor da receita aplicada. Um vetor por par reúne as posições espaciais desse par; não é uma descrição verbal do movimento.</p><p id="vTemporalComparison" class="temporal-comparisons"></p><div class="downloads"><a id="vArrays">Baixar todos os tokens</a><a id="vPairs">Baixar vetores por par temporal</a><a id="vDownloadRecord">Baixar registro e observações</a></div></section>`;
let ident=null,meta=null,prepared=null,result=null,objectUrl=null,play=null,poll=null,current=0;
const recipePanel=new LabRecipe($('videoRecipe'),{mode:'video',apply:async recipe=>{
  setBusy(true);try{await post('/api/video/reanalyze',{id:ident,recipe});await check()}finally{setBusy(false)}
}});window.videoRecipe=recipePanel;
const fields=['vFile','vStart','vEnd','vCount','vLimit','vBackground','vNotes'];
const seconds=n=>n.toLocaleString('pt-BR',{maximumFractionDigits:6});
function validateTimes(){
  let error='';
  if(meta&&ident){
    const start=$('vStart').valueAsNumber,end=$('vEnd').valueAsNumber;
    const maxEnd=Math.min(meta.duration,600,Number.isFinite(start)?start+60:60);
    $('vStart').max=String(Math.min(meta.duration,600));$('vEnd').max=String(maxEnd);
    $('vEndHelp').textContent=`O arquivo termina em ${seconds(meta.duration)} s. Fim máximo para este trecho: ${seconds(maxEnd)} s.`;
    if(!Number.isFinite(start)||!Number.isFinite(end))error='Preencha o início e o fim em segundos.';
    else if(start<0)error='O início deve ser zero ou maior.';
    else if(end>meta.duration+1e-9)error=`O arquivo dura ${seconds(meta.duration)} s. O fim informado (${seconds(end)} s) ultrapassa essa duração.`;
    else if(end<=start)error='O fim precisa ser maior que o início.';
    else if(end>600)error='Escolha um trecho dentro dos primeiros 600 segundos do arquivo.';
    else if(end-start>60+1e-9)error='Esta versão aceita até 60 segundos por trecho. Aproxime o início do fim ou diminua o fim.';
    $('vUseEnd').disabled=videoBusy||!Number.isFinite(start)||start<0||start>=meta.duration||meta.duration>600||meta.duration-start>60;
  }else{$('vEndHelp').textContent='A duração e os limites aparecem assim que o arquivo é lido.';$('vUseEnd').disabled=true;}
  $('vTimeError').textContent=error;$('vTimeError').classList.toggle('hidden',!error);
  $('vEnd').setAttribute('aria-invalid',String(!!error));
  $('vPrepare').disabled=videoBusy||!ident||!!error;
  return !error&&!!ident;
}
function setBusy(on){videoBusy=on;lock(on);for(const id of fields)$(id).disabled=on;validateTimes();$('vRun').disabled=on||!prepared;recipePanel.setBusy(on||busy)}
function stopPlay(){clearInterval(play);play=null;$('vPlay').textContent='Reproduzir amostra · 2 quadros/s'}
function invalidate(){if(prepared||result)$('vStatus').textContent='A entrada mudou: prepare novamente e execute o encoder para analisar estas condições.';recipePanel.availability('dirty');stopPlay();prepared=null;result=null;$('vPreparedPanel').classList.add('hidden');$('vResults').classList.add('hidden');validateTimes();$('vRun').disabled=true}
for(const id of ['vStart','vEnd','vCount','vLimit','vBackground'])$(id).oninput=invalidate;
$('vFile').onchange=async()=>{const f=$('vFile').files[0];if(!f)return;ident=null;meta=null;$('vDurationBox').classList.add('hidden');$('vOriginalBox').classList.add('hidden');invalidate();if(f.size>50000000){$('vStatus').textContent='Use um arquivo de até 50 MB.';return}setBusy(true);$('vStatus').textContent='Lendo a duração e o formato, sem executar o encoder…';try{const encoded=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Não foi possível ler o arquivo.'));r.readAsDataURL(f)});const j=await post('/api/video/upload',{file:encoded});ident=j.id;meta=j.meta;if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(f);$('vOriginalVideo').pause();$('vOriginalVideo').removeAttribute('src');$('vOriginalVideo').classList.toggle('hidden',meta.kind==='gif');$('vOriginalGif').classList.toggle('hidden',meta.kind!=='gif');$(meta.kind==='gif'?'vOriginalGif':'vOriginalVideo').src=objectUrl;$('vOriginalBox').classList.remove('hidden');$('vMeta').textContent=`${f.name} · ${meta.width} × ${meta.height} · ${meta.duration.toFixed(3)} s${meta.frames?' · '+meta.frames+' quadros':''}`;$('vStart').value=0;$('vEnd').value=String(Math.min(meta.duration,60));$('vDuration').textContent=seconds(meta.duration)+' segundos';$('vDurationNote').textContent=meta.kind==='gif'?'Duração de uma passagem do GIF, sem contar as repetições da animação.':'Duração da faixa de vídeo lida do arquivo.';$('vDurationBox').classList.remove('hidden');$('vStatus').textContent='Arquivo pronto. Escolha o trecho e prepare a amostra.'+(meta.timing_fallback_frames?' Quadros sem duração válida usam 0,1 s; isso ficará registrado.':'')}catch(e){$('vStatus').textContent=e.message;$('vOriginalBox').classList.add('hidden')}finally{setBusy(false)}};
$('vUseEnd').onclick=()=>{if(!meta||$('vUseEnd').disabled)return;$('vEnd').value=String(meta.duration);invalidate()};
$('vPrepare').onclick=async()=>{if(!validateTimes())return;invalidate();setBusy(true);$('vStatus').textContent='Selecionando quadros e preparando os pixels…';try{prepared=await post('/api/video/prepare',{id:ident,start:Number($('vStart').value),end:Number($('vEnd').value),count:Number($('vCount').value),limit:Number($('vLimit').value),background:$('vBackground').value});const p=prepared.info;$('vSummary').textContent=`${p.sampled_frames} quadros → ${p.temporal_pairs} pares · ${p.prepared_wh.join(' × ')} pixels por quadro · entrada ${p.pixel_values_shape.join(' × ')} → ${p.expected_after_tokens} tokens esperados depois do merger.`;$('vRepeated').textContent=p.repeated_samples?`${p.repeated_samples} seleções repetem quadros do arquivo. Isso é mostrado nos números e tempos abaixo.`:'Todos os quadros selecionados têm índices diferentes.';$('vRecord').textContent=JSON.stringify(p,null,2);$('vSlider').max=p.sampled_frames-1;$('vFrames').replaceChildren();p.timestamps.forEach((time,i)=>{const b=document.createElement('button');b.className='videoFrame';b.setAttribute('aria-pressed','false');const img=document.createElement('img');img.src=prepared.frames[i]+'?t='+Date.now();img.alt=`Entrada preparada ${i+1}`;const label=document.createElement('span');label.textContent=`Par ${Math.floor(i/2)+1} · amostra ${i+1}\nQuadro ${p.frame_indices[i]+1} · ${time.toFixed(3)} s`;b.append(img,label);b.onclick=()=>{stopPlay();showFrame(i)};$('vFrames').append(b)});$('vPreparedPanel').classList.remove('hidden');$('vProgress').value=0;$('vRunStatus').textContent='Entrada preparada. O encoder ainda não foi executado.';showFrame(0);recipePanel.availability('prepared');$('vStatus').textContent='Preparação concluída. Confira a sequência abaixo.'}catch(e){prepared=null;$('vStatus').textContent=e.message}finally{setBusy(false)}};
function showFrame(i){if(!prepared)return;current=i;$('vSlider').value=i;const p=prepared.info;$('vSelectedOriginal').src=prepared.originals[i]+'?t='+ident;const image=new Image();image.onload=()=>{if(i!==current)return;const c=$('vCanvas');c.width=image.width;c.height=image.height;const x=c.getContext('2d');x.drawImage(image,0,0);if($('vGrid').checked){x.strokeStyle='rgba(255,0,130,.85)';x.lineWidth=.7;x.beginPath();for(let n=16;n<c.width;n+=16){x.moveTo(n,0);x.lineTo(n,c.height)}for(let n=16;n<c.height;n+=16){x.moveTo(0,n);x.lineTo(c.width,n)}x.stroke()}};image.src=prepared.frames[i]+'?t='+ident;$('vFrameCaption').textContent=`Amostra ${i+1} de ${p.sampled_frames} · par ${Math.floor(i/2)+1} · instante solicitado ${p.requested_times[i].toFixed(3)} s · quadro ${p.frame_indices[i]+1}, iniciado em ${p.timestamps[i].toFixed(3)} s`;[...$('vFrames').children].forEach((b,n)=>b.setAttribute('aria-pressed',String(n===i)))}
$('vSlider').oninput=()=>{stopPlay();showFrame(Number($('vSlider').value))};$('vGrid').onchange=()=>showFrame(current);
$('vPlay').onclick=()=>{if(play){stopPlay();return}if(!prepared)return;$('vPlay').textContent='Pausar amostra';play=setInterval(()=>{if(root.classList.contains('hidden')){stopPlay();return}showFrame((current+1)%prepared.info.sampled_frames)},500)};
$('vRun').onclick=async()=>{stopPlay();setBusy(true);$('vResults').classList.add('hidden');$('vRunStatus').textContent='Iniciando o encoder…';try{await post('/api/video/run',{id:ident,notes:$('vNotes').value,recipe:recipePanel.value()});poll=setInterval(check,1200)}catch(e){$('vRunStatus').textContent=e.message;setBusy(false)}};
let checking=false;
async function check(){if(checking)return;checking=true;try{const response=await fetch('/api/video/job/'+ident);const j=await response.json();if(!response.ok)throw Error(j.error||'Falha na consulta');$('vRunStatus').textContent=j.status;$('vProgress').value=j.completed_blocks;if(j.state==='done'){clearInterval(poll);result=j;recipePanel.applied(j.analysis.recipe);$('vAppliedRecipe').textContent='Receita aplicada: '+LabRecipe.describe(j.analysis.recipe);setBusy(false);$('vResults').classList.remove('hidden');$('vShapes').textContent=`Antes do merger: ${j.info.antes_shape.join(' × ')}. Depois: ${j.info.depois_shape.join(' × ')}. Execução: ${j.info.tempo_inferencia_s.toFixed(2)} s.`;const previousPair=$('vPair').value;$('vPair').replaceChildren(new Option('Agregação da sequência inteira','-1'));j.pairs.forEach((_,i)=>$('vPair').add(new Option(`Par ${i+1} · amostras ${i*2+1} e ${i*2+2}`,String(i))));if([...$('vPair').options].some(o=>o.value===previousPair))$('vPair').value=previousPair;drawVector();for(const [id,name] of [['vArrays','representacoes.npz'],['vPairs','pares_temporais.npz'],['vDownloadRecord','registro.json']])$(id).href=`/video-file/${ident}/${name}`}else if(j.state==='error')throw Error(j.status)}catch(e){clearInterval(poll);$('vRunStatus').textContent=e.message;setBusy(false)}finally{checking=false}}
let barVector=null,barStart=0,barStep=1,barSelected=null,barFrame=0;
function chart(values){if(!values?.length)return;if(barVector!==values){barVector=values;barStart=0;barSelected=null}const width=Math.max(280,$('vBars').clientWidth);barStep=(width-67)/48;const scroller=$('vBarScroll');$('vBarScrollSpace').style.width=(scroller.clientWidth+Math.max(0,values.length-48)*barStep)+'px';scroller.scrollLeft=barStart*barStep;paintBars()}
function paintBars(){if(!barVector)return;const svg=$('vBars');svg.replaceChildren();const values=barVector.slice(barStart,barStart+48),ns='http://www.w3.org/2000/svg',scale=Math.ceil(Math.max(...values.map(Math.abs),.0001)*100)/100;
const width=Math.max(280,svg.clientWidth),span=width-67;svg.setAttribute('viewBox',`0 0 ${width} 180`);
function el(tag,attrs,text){const n=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text)n.textContent=text;svg.append(n);return n}
for(const [y,t]of [[18,'+'+scale.toFixed(2)],[90,'0'],[162,'−'+scale.toFixed(2)]]){el('line',{x1:57,y1:y,x2:width-7,y2:y,stroke:y===90?'#6b8295':'#d9e2ea'});el('text',{x:4,y:y+4,fill:'#526474','font-size':13},t)}
values.forEach((v,i)=>{const index=barStart+i,h=Math.abs(v)/scale*72,label=`Coordenada ${index+1}: ${v>=0?'+':''}${v.toFixed(8)}`;const r=el('rect',{x:60+i*span/48,y:v>=0?90-h:90,width:span/48*.72,height:Math.max(h,.3),fill:v>=0?'#1359b7':'#b66215',tabindex:0,role:'img','aria-label':label,'data-coordinate':index+1,stroke:index===barSelected?'#102236':'none','stroke-width':1.5});const title=document.createElementNS(ns,'title');title.textContent=label;r.append(title);r.onmouseenter=r.onfocus=()=>{$('vBarReading').textContent=label};r.onclick=()=>{barSelected=index;for(const rect of svg.querySelectorAll('rect'))rect.setAttribute('stroke',Number(rect.dataset.coordinate)===index+1?'#102236':'none');$('vBarReading').textContent=label+' · selecionada'}});
$('vBarScale').textContent=`Escala deste trecho: −${scale.toFixed(2)} a +${scale.toFixed(2)}. A escala vertical se ajusta às 48 coordenadas visíveis; a largura das barras e o tamanho do gráfico permanecem iguais. Compare os valores numéricos entre trechos.`;
$('vBarRange').textContent=`Coordenadas ${barStart+1}–${barStart+values.length} de ${barVector.length.toLocaleString('pt-BR')}. Arraste a rolagem, deslize na horizontal ou use as setas com a rolagem em foco.`;
svg.setAttribute('aria-label',`Coordenadas ${barStart+1} a ${barStart+values.length} do vetor normalizado`);
if(barSelected!==null){const v=barVector[barSelected];$('vBarReading').textContent=`Coordenada ${barSelected+1}: ${v>=0?'+':''}${v.toFixed(8)} · selecionada${barSelected<barStart||barSelected>=barStart+48?' (fora do trecho visível)':''}`}else $('vBarReading').textContent='Clique numa barra, passe o ponteiro ou use Tab para consultar sua coordenada e seu valor.';
}
function moveBars(index){if(!barVector)return;const next=Math.max(0,Math.min(index,barVector.length-48));$('vBarScroll').scrollLeft=next*barStep;if(barStart!==next){barStart=next;paintBars()}}
$('vBarScroll').onscroll=()=>{cancelAnimationFrame(barFrame);barFrame=requestAnimationFrame(()=>{if(!barVector)return;const next=Math.max(0,Math.min(Math.round($('vBarScroll').scrollLeft/barStep),barVector.length-48));if(next!==barStart){barStart=next;paintBars()}})};
$('vBarScroll').onkeydown=event=>{const moves={ArrowLeft:barStart-1,ArrowRight:barStart+1,PageUp:barStart-48,PageDown:barStart+48,Home:0,End:barVector?barVector.length-48:0};if(event.key in moves){event.preventDefault();moveBars(moves[event.key])}};
$('vBars').addEventListener('wheel',event=>{if(Math.abs(event.deltaX)>Math.abs(event.deltaY)||event.shiftKey){event.preventDefault();$('vBarScroll').scrollLeft+=(event.deltaX||event.deltaY)*(event.deltaMode===1?16:1)}},{passive:false});
let barDrag=null;
$('vBars').onpointerdown=event=>{if(event.button===0)barDrag={id:event.pointerId,x:event.clientX,y:event.clientY,left:$('vBarScroll').scrollLeft,dragging:false}};
$('vBars').onpointermove=event=>{if(!barDrag||barDrag.id!==event.pointerId)return;const dx=event.clientX-barDrag.x,dy=event.clientY-barDrag.y;if(!barDrag.dragging&&Math.abs(dx)>5&&Math.abs(dx)>Math.abs(dy)){barDrag.dragging=true;$('vBars').setPointerCapture(event.pointerId)}if(barDrag.dragging)$('vBarScroll').scrollLeft=barDrag.left-dx};
$('vBars').onpointerup=$('vBars').onpointercancel=()=>{barDrag=null};

new ResizeObserver(()=>{if(barVector&&$('vBars').clientWidth>0)chart(barVector)}).observe($('vBars'));
function vector(){const p=Number($('vPair').value),before=$('vStage').value==='before';return p<0?(before?result.vector_before:result.vector):(before?result.pairs_before[p]:result.pairs[p])}
function drawVector(){if(!result)return;const stage=$('vStage').value,scores=result.temporal_comparisons[stage],label={cosine:'Cosseno',euclidean:'Distância euclidiana',dot:'Produto escalar'}[result.analysis.recipe.metric];$('vTemporalComparison').textContent=scores.length?label+' entre pares temporais consecutivos: '+scores.map((v,i)=>`par ${i+1} → ${i+2}: ${v.toFixed(8)}`).join(' · '):'A sequência tem um único par temporal; não há outro par para comparar.';chart(vector());const values=vector(),scale=Math.max(...values.map(Math.abs),.001),svg=$('vChart'),ns='http://www.w3.org/2000/svg';svg.replaceChildren();const path=document.createElementNS(ns,'path');path.setAttribute('d',values.map((v,i)=>`${i?'L':'M'}${40+i*940/Math.max(1,values.length-1)},${105-v/scale*88}`).join(' '));path.setAttribute('fill','none');path.setAttribute('stroke','#1359b7');path.setAttribute('stroke-width','1');svg.append(path);for(const [text,x,y] of [['1',40,215],[values.length.toLocaleString('pt-BR'),925,215],[scale.toFixed(3),0,15],['0',10,109],[(-scale).toFixed(3),0,200]]){const t=document.createElementNS(ns,'text');t.textContent=text;t.setAttribute('x',x);t.setAttribute('y',y);t.setAttribute('font-size','12');svg.append(t)}$('vReading').textContent='Passe o ponteiro pelo gráfico para consultar uma coordenada. A escala se ajusta ao vetor selecionado.'}
$('vStage').onchange=drawVector;$('vPair').onchange=drawVector;$('vChart').onpointermove=e=>{if(!result)return;const b=$('vChart').getBoundingClientRect(),i=Math.max(0,Math.min(vector().length-1,Math.round(((e.clientX-b.left)/b.width*1000-40)/940*(vector().length-1))));$('vReading').textContent=`Coordenada ${i+1}: ${vector()[i].toFixed(8)}`};
})();
